function generateReviewHTML(reviewerName, reviewText, rating = 5) {
    // Validate rating
    if (rating < 1 || rating > 5 || isNaN(rating)) {
        rating = 5; // default to 5 if invalid
    }

    // Generate stars
    let stars = '';
    for (let i = 1; i <= 5; i++) {
        if (i <= rating) {
            stars += '★'; // filled star
        } else {
            stars += '☆'; // empty star
        }
    }

    // Build the HTML
    const html = `
        <div class="review">
            <div class="reviewer-info">
                <strong>${reviewerName}</strong>
                <span class="rating">${stars}</span>
            </div>
            <p class="review-text">${reviewText}</p>
        </div>
    `;

    return html;
}

