from requests.exceptions import RequestException

class PaymentGateway:
    def __init__(self, api_url, auth_url, client_id, client_secret):
        self.api_url = api_url
        self.auth_url = auth_url
        self.client_id = client_id
        self.client_secret = client_secret
        self.access_token = None
        self.session = requests.Session()

    def authenticate(self):
        """Authenticate with the payment processor API"""
        try:
            response = self.session.post(
                self.auth_url,
                data={
                    'client_id': self.client_id,
                    'client_secret': self.client_secret,
                    'grant_type': 'client_credentials'
                },
                timeout=10
            )
            response.raise_for_status()
            self.access_token = response.json()['access_token']
            return True
        except RequestException as e:
            raise ConnectionError(f"Authentication failed: {str(e)}") from e
        except KeyError:
            raise ValueError("Invalid authentication response format")

    def get_transaction_status(self, transaction_id):
        """Retrieve transaction status by ID"""
        if not self.access_token:
            if not self.authenticate():
                raise PermissionError("Failed to obtain access token")

        endpoint = f"{self.api_url}/transactions/{transaction_id}"
        try:
            response = self.session.get(
                endpoint,
                headers={'Authorization': f'Bearer {self.access_token}'},
                timeout=10
            )

            # Handle token expiration (401 Unauthorized)
            if response.status_code == 401:
                self.authenticate()
                response = self.session.get(
                    endpoint,
                    headers={'Authorization': f'Bearer {self.access_token}'},
                    timeout=10
                )

            response.raise_for_status()
            return response.json()

        except RequestException as e:
            if e.response is not None:
                if e.response.status_code == 404:
                    raise ValueError("Transaction not found")
                if e.response.status_code == 403:
                    raise PermissionError("Insufficient permissions")
            raise ConnectionError(f"API request failed: {str(e)}") from e
        except json.JSONDecodeError:
            raise ValueError("Invalid JSON response from server")

