import requests
import json
from typing import Dict, Union, Optional

def fetch_shipping_rates(
    carrier_api_url: str,
    destination: Dict[str, Union[str, int, float]],
    api_key: Optional[str] = None,
    timeout: int = 10,
    retries: int = 2
) -> Dict[str, Union[Dict, str]]:
    """
    Fetches real-time shipping rates from a carrier API.

    Args:
        carrier_api_url: The endpoint URL for the carrier's API
        destination: Dictionary containing destination details (e.g.,
                    {'country': 'US', 'postal_code': '10001', 'city': 'New York'})
        api_key: Optional API key for authenticated requests
        timeout: Request timeout in seconds
        retries: Number of retry attempts for failed requests

    Returns:
        Dictionary with either:
        - 'rates': The shipping rates response on success
        - 'error': Error message if the request failed
    """
    headers = {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    }

    if api_key:
        headers['Authorization'] = f'Bearer {api_key}'

    payload = {
        'destination': destination
    }

    for attempt in range(retries + 1):
        try:
            response = requests.post(
                carrier_api_url,
                headers=headers,
                data=json.dumps(payload),
                timeout=timeout
            )

            # Check for successful response
            if response.status_code == 200:
                return {
                    'rates': response.json()
                }

            # Handle API-specific error responses
            try:
                error_data = response.json()
                error_msg = error_data.get('message', f'Carrier API error: {response.status_code}')
            except ValueError:
                error_msg = f'Carrier API returned status code: {response.status_code}'

            # Don't retry on client errors (4xx)
            if 400 <= response.status_code < 500:
                return {
                    'error': error_msg
                }

        except requests.exceptions.Timeout:
            if attempt == retries:
                return {
                    'error': f'Request timed out after {timeout} seconds'
                }
        except requests.exceptions.ConnectionError:
            if attempt == retries:
                return {
                    'error': 'Failed to connect to carrier API'
                }
        except requests.exceptions.RequestException as e:
            if attempt == retries:
                return {
                    'error': f'Request failed: {str(e)}'
                }
        except json.JSONDecodeError:
            if attempt == retries:
                return {
                    'error': 'Invalid response from carrier API'
                }

    return {
        'error': 'Max retries exceeded'
    }

def search_students(students, name=None, major=None, min_gpa=None, max_gpa=None):
    """
    Search for students based on name (partial), major, and GPA range.

    Parameters:
    - students (list of dict): List of student records (dict with keys like 'name', 'major', 'gpa')
    - name (str): Partial student name to search for (case-insensitive)
    - major (str): Major to filter by (case-insensitive)
    - min_gpa (float): Minimum GPA (inclusive)
    - max_gpa (float): Maximum GPA (inclusive)

    Returns:
    - List of student dictionaries that match the criteria
    """
    results = []

    for student in students:
        match = True

        # Filter by partial name (case-insensitive)
        if name:
            if name.lower() not in student.get('name', '').lower():
                match = False

        # Filter by major (case-insensitive)
        if major:
            if student.get('major', '').lower() != major.lower():
                match = False

        # Filter by GPA range
        if min_gpa is not None or max_gpa is not None:
            gpa = student.get('gpa')
            if gpa is None:
                match = False
            else:
                if min_gpa is not None and gpa < min_gpa:
                    match = False
                if max_gpa is not None and gpa > max_gpa:
                    match = False

        if match:
            results.append(student)

    return results

