import os
import pickle
import json
import yaml
from typing import Dict, Any, Optional

def load_course_config(filename: str) -> Optional[Dict[str, Any]]:
    """
    Loads course configuration from a file, supporting .pickle, .json, and .yaml formats.

    Args:
        filename (str): Path to the configuration file.

    Returns:
        dict: The loaded configuration as a dictionary, or None if loading fails.
    """
    # Normalize the filename to handle case-insensitivity in OS
    filename = os.path.abspath(filename)

    if not os.path.exists(filename):
        print(f"Error: File '{filename}' not found.")
        return None

    _, ext = os.path.splitext(filename)
    ext = ext.lower()

    try:
        with open(filename, 'r') as file:
            if ext == '.pickle':
                # Pickle files need to be opened in binary mode
                with open(filename, 'rb') as f:
                    return pickle.load(f)
            elif ext == '.json':
                return json.load(file)
            elif ext in ('.yaml', '.yml'):
                return yaml.safe_load(file)
            else:
                print(f"Error: Unsupported file format for '{filename}'. Supported formats: .pickle, .json, .yaml")
                return None
    except (pickle.PickleError, json.JSONDecodeError, yaml.YAMLError, IOError) as e:
        print(f"Error loading configuration from '{filename}': {e}")
        return None

import os
import pickle
import json
import yaml

def load_course_config(file_path):
    """
    Load course configuration from a file.

    Supports pickle, JSON, and YAML formats.
    Detects format by file extension.

    Args:
        file_path (str): Path to the configuration file.

    Returns:
        dict: Parsed configuration as a Python dictionary.

    Raises:
        FileNotFoundError: If the file does not exist.
        ValueError: If the file format is not supported or the file is malformed.
    """
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"The file '{file_path}' does not exist.")

    try:
        with open(file_path, 'r', encoding='utf-8') as file:
            _, ext = os.path.splitext(file_path)
            ext = ext.lower()

            if ext == '.pkl' or ext == '.pickle':
                return pickle.load(file)
            elif ext == '.json':
