import requests
import json

def fetch_library_availability(course_id, api_base_url, api_username, api_password):
    """
    Fetches reading list availability from a library catalog API for a given course ID.

    Args:
        course_id (str): The course ID to fetch availability for
        api_base_url (str): Base URL of the library catalog API
        api_username (str): API authentication username
        api_password (str): API authentication password

    Returns:
        dict: JSON response containing availability information or error details
    """

    # API endpoint (adjust based on actual API structure)
    endpoint = f"{api_base_url}/courses/{course_id}/reading-list"

    try:
        # Make the API request with authentication
        response = requests.get(
            endpoint,
            auth=(api_username, api_password),
            headers={
                'Accept': 'application/json',
                'Content-Type': 'application/json'
            },
            timeout=30  # 30 second timeout
        )

        # Check for successful response
        response.raise_for_status()

        # Return the JSON response
        return response.json()

    except requests.exceptions.HTTPError as http_err:
        # Handle HTTP errors (4xx, 5xx)
        error_details = {
            'error': 'HTTP Error',
            'status_code': response.status_code,
            'message': str(http_err),
            'course_id': course_id
        }
        return error_details

    except requests.exceptions.ConnectionError as conn_err:
        # Handle connection errors
        return {
            'error': 'Connection Error',
            'message': str(conn_err),
            'course_id': course_id
        }

    except requests.exceptions.Timeout as timeout_err:
        # Handle timeout errors
        return {
            'error': 'Timeout Error',
            'message': str(timeout_err),
            'course_id': course_id
        }

    except requests.exceptions.RequestException as req_err:
        # Handle other request exceptions
        return {
            'error': 'Request Error',
            'message': str(req_err),
            'course_id': course_id
        }

    except json.JSONDecodeError as json_err:
        # Handle JSON parsing errors
        return {
            'error': 'JSON Decode Error',
            'message': str(json_err),
            'course_id': course_id,
            'response_text': response.text if 'response' in locals() else None
        }

