        course_id (str): The course identifier (e.g., "CS101")
        library_api_config (dict): Configuration dictionary containing:
            - api_base_url: Base URL of the library catalog API
            - api_key: API authentication key
            - api_secret: API authentication secret (if required)
            - api_auth_endpoint: Authentication endpoint (if required)
            - api_catalog_endpoint: Catalog endpoint for reading lists

    Returns:
        dict: JSON response containing reading list availability information
        or error details if the request fails
    """

    # Prepare the API endpoints
    base_url = library_api_config['api_base_url']
    auth_url = f"{base_url}/{library_api_config.get('api_auth_endpoint', 'auth')}"
    catalog_url = f"{base_url}/{library_api_config['api_catalog_endpoint']}"

    # Prepare headers
    headers = {
        'Content-Type': 'application/json',
        'Accept': 'application/json'
    }

    try:
        # Step 1: Authenticate with the API
        auth_data = {
            'api_key': library_api_config['api_key'],
