    Fetches reading list availability from the library catalog system by course ID.

    Args:
        course_id (str): The course identifier to check availability for

    Returns:
        dict: JSON response with structure:
            {
                'success': bool,
                'data': dict | None,
                'error': str | None
            }
    """
    # Configuration - move these to environment variables in production
    API_AUTH_URL = "https://api.library.edu/auth/token"
    API_CATALOG_URL = f"https://api.library.edu/catalog/availability/{course_id}"
    CLIENT_ID = os.environ.get("LIBRARY_API_CLIENT_ID")
    CLIENT_SECRET = os.environ.get("LIBRARY_API_CLIENT_SECRET")

    # Validate credentials
    if not all([CLIENT_ID, CLIENT_SECRET]):
        return {
            'success': False,
            'data': None,
            'error': 'API credentials not configured'
        }

    try:
        # Authenticate and get access token
        auth_response = requests.post(
            API_AUTH_URL,
            data={
                'client_id': CLIENT_ID,
                'client_secret': CLIENT_SECRET,
                'grant_type': 'client_credentials'
            },
            timeout=10
        )

        # Handle authentication errors
        if auth_response.status_code != 200:
            return {
                'success': False,
                'data': None,
                'error': f'Authentication failed: {auth_response.text}'
            }

        access_token = auth_response.json().get('access_token')
        if not access_token:
            return {
                'success': False,
                'data': None,
                'error': 'No access token in authentication response'
            }

        # Fetch catalog availability
        catalog_response = requests.get(
            API_CATALOG_URL,
            headers={'Authorization': f'Bearer {access_token}'},
            timeout=10
        )

        # Handle catalog response
        if catalog_response.status_code == 200:
            return {
                'success': True,
                'data': catalog_response.json(),
                'error': None
            }

        return {
            'success': False,
            'data': None,
            'error': f'Catalog request failed: {catalog_response.status_code} - {catalog_response.text}'
        }

    except RequestException as e:
        return {
            'success': False,
            'data': None,
            'error': f'Network error: {str(e)}'
        }
    except Exception as e:
        return {
            'success': False,
