import requests
import json
import time

def fetch_publications(api_url, search_query, timeout=10, max_retries=3):
    """
    Fetches academic publications from a journal API.

    Args:
        api_url (str): The base URL of the journal API.
        search_query (str): The search query to use.
        timeout (int, optional): The request timeout in seconds. Defaults to 10.
        max_retries (int, optional): The maximum number of retries. Defaults to 3.

    Returns:
        dict: A dictionary containing the publication data, or None if an error occurred.
              Returns an empty dictionary if no results are found.

    Raises:
        TypeError:  If api_url or search_query are not strings.
        ValueError: If timeout or max_retries are not positive integers.
    """

    if not isinstance(api_url, str):
        raise TypeError("api_url must be a string.")
    if not isinstance(search_query, str):
        raise TypeError("search_query must be a string.")
    if not isinstance(timeout, int) or timeout <= 0:
        raise ValueError("timeout must be a positive integer.")
    if not isinstance(max_retries, int) or max_retries <= 0:
        raise ValueError("max_retries must be a positive integer.")


    for attempt in range(max_retries):
        try:
            # Construct the full API request URL.  Adapt this to the specific API.
            # This example assumes the API takes the search query as a parameter 'q'
            full_url = f"{api_url}?q={search_query}"

            response = requests.get(full_url, timeout=timeout, verify=True)  # Verify SSL Certificate
            response.raise_for_status()  # Raise HTTPError for bad responses (4xx or 5xx)

            # Attempt to parse the response as JSON
            try:
                data = response.json()
                return data  # Return the data if successful
            except json.JSONDecodeError:
                print(f"Error decoding JSON response. Response text: {response.text}")
                return None  # Or handle the error differently, e.g., log it


        except requests.exceptions.ConnectionError as e:
            print(f"Connection error: {e}. Attempt {attempt + 1}/{max_retries}")
            if attempt < max_retries - 1:
                time.sleep(2**(attempt)) # Exponential backoff
            else:
                print("Max retries reached.  Unable to connect.")
                return None
        except requests.exceptions.Timeout as e:
            print(f"Timeout error: {e}. Attempt {attempt + 1}/{max_retries}")
            if attempt < max_retries - 1:
                time.sleep(2**(attempt))  # Exponential backoff
            else:
                print("Max retries reached.  Request timed out.")
                return None
        except requests.exceptions.HTTPError as e:
            print(f"HTTP Error: {e}. Status code: {response.status_code}")
            if response.status_code == 404:
                # Handle 404 Not Found - return empty dictionary instead of erroring
                return {}
            else:
                return None
        except Exception as e:  # Catch-all for other potential errors
            print(f"An unexpected error occurred: {e}")
            return None

    return None  # Return None if all retries fail


