import requests
import json

def get_reading_list_availability(course_id, api_url, api_username=None, api_password=None):
    """
    Fetches reading list availability from the library catalog API for a given course ID.

    Parameters:
    - course_id (str): Course identifier.
    - api_url (str): Base URL of the library catalog API.
    - api_username (str, optional): API username for authentication.
    - api_password (str, optional): API password for authentication.

    Returns:
    - dict: Parsed JSON response from the API.
    - None: On failure or invalid input.
    """

    if not course_id or not api_url:
        return {"error": "Missing required parameters: course_id or api_url"}

    # Construct the full URL
    endpoint = f"{api_url}/availability/{course_id}"

    try:
        # Make the GET request with authentication
        response = requests.get(
            endpoint,
            auth=(api_username, api_password) if api_username and api_password else None,
            headers={'Accept': 'application/json'}
        )

        # Check for HTTP errors
        response.raise_for_status()

        # Return parsed JSON
        return response.json()

    except requests.exceptions.RequestException as e:
        return {"error": f"API request failed: {str(e)}"}
    except json.JSONDecodeError:
        return {"error": "Failed to parse JSON response"}

import requests

def fetch_publications(api_url, query, params=None, timeout=10):
    """
    Fetch academic publications from a journal API based on a search query.

    Parameters:
        api_url (str): The base URL of the journal API's search endpoint.
        query (str): The search query (e.g., "climate change").
        params (dict, optional): Additional query parameters (e.g., API key, page, limit).
        timeout (int, optional): Request timeout in seconds. Default is 10.

    Returns:
        dict: The parsed JSON response from the API or an error message if failed.
    """
    # Ensure params is a dictionary
    if params is None:
        params = {}

    # Add the search query to the parameters
    params['q'] = query  # Adjust the key based on the actual API (e.g., 'query', 'term')

    try:
        # Make the GET request to the API
        response = requests.get(api_url, params=params, timeout=timeout)
        response.raise_for_status()  # Raises an HTTPError for bad responses (4xx, 5xx)

        # Parse and return the JSON response
        return response.json()

    except requests.exceptions.RequestException as e:
        # Handle any request-related exceptions
        return {
            "error": "Request failed",
            "message": str(e)
        }

    except ValueError as e:
        # Handle JSON parsing errors
        return {
            "error": "Invalid JSON response",
            "message": str(e)
        }
